// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0 && amount <= address(actor).balance + 1e30);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(0);

        (, uint256 credited) = c.Acc(actor);
        assertTrue(credited == address(c).balance);
    }
}
